summary:
bash: mkdir -p /root/klee-smoke && cd /root/klee-smoke
cat > test.c <<'EOF'
#include <klee/klee.h>
int main(void) {
  int a;
  klee_make_symbolic(&a, sizeof(a), "a");
  if (a == 42) return 1;
  return 0;
}
EOF
clang-16 -I/usr/local/include -emit-llvm -c -g -O0 -Xclang -disable-O0-optnone test.c -o test.bc
rm -rf klee-out-0
klee --libc=none --search=dfs test.bc
echo "klee_exit=$?"
ls klee-out-0
cat klee-out-0/messages.txt 2>/dev/null | head

